    queue<TreeNode *> queue;
    queue.push(root);
    TreeNode *currentNode = nullptr, *previousNode = nullptr;
    while (!queue.empty()) {
      currentNode = queue.front();
      queue.pop();
      if (previousNode != nullptr) {
        previousNode->next = currentNode;
      }
      previousNode = currentNode;

